hints:
for each right end of the window:
    increment count of entering value:
        erase its old (freq, value) pair from whichever set holds it
        insert the new pair into the rest set, then rebalance
    if window size exceeds k, decrement count of leaving value the same way
    rebalance = fill top from rest's largest while top < x;
                move top's smallest to rest while top > x;
                while rest's largest > top's smallest, swap them (fixing the sum)
    when the window is full, record the sum

code.cpp:
class Solution {
public:
    vector<long long> findXSum(vector<int>& nums, int k, int x) {
        int n = nums.size();
        unordered_map<int, int> cnt;
        cnt.reserve(2 * n);
        set<pair<int, int>> top, rest; // (frequency, value)
        long long sum = 0;

        auto fillTop = [&]() {
            while ((int)top.size() < x && !rest.empty()) {
                auto it = prev(rest.end());
                sum += (long long)it->first * it->second;
                top.insert(*it);
                rest.erase(it);
            }
        };
        auto addPair = [&](pair<int, int> p) {
            rest.insert(p);
            fillTop();
            while (!rest.empty() && *prev(rest.end()) > *top.begin()) {
                pair<int, int> a = *prev(rest.end()), b = *top.begin();
                sum += (long long)a.first * a.second - (long long)b.first * b.second;
                rest.erase(prev(rest.end()));
                top.erase(top.begin());
                top.insert(a);
                rest.insert(b);
            }
        };
        auto removePair = [&](pair<int, int> p) {
            if (top.erase(p)) sum -= (long long)p.first * p.second;
            else rest.erase(p);
            fillTop();
        };

        vector<long long> ans;
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            int c = cnt[v]++;
            if (c > 0) removePair({c, v});
            addPair({c + 1, v});
            if (i >= k) {
                int u = nums[i - k];
                int c2 = cnt[u]--;
                removePair({c2, u});
                if (c2 > 1) addPair({c2 - 1, u});
            }
            if (i >= k - 1) ans.push_back(sum);
        }
        return ans;
    }
};
